result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/emitter/src/emitter.ts", "content": "/**
 * Typed event emitter.
 *
 * Events are described as a map from event name to a tuple of argument types:
 *
 * ```ts
 * interface Events {
 *   message: [text: string, id: number];
 *   close: [];
 * }
 *
 * const emitter = new Emitter<Events>();
 * emitter.on('message', (text, id) => console.log(text, id));
 * ```
 */

type ListenerFn = (...args: any[]) => void;

interface Entry {
  listener: ListenerFn;
  once: boolean;
  /** Set when the entry is removed; lets an in-flight emit snapshot skip it. */
  removed: boolean;
}

export class Emitter<Events extends Record<string, unknown[]>> {
  #listeners = new Map<keyof Events, Entry[]>();
  #anyListeners: Entry[] = [];

  /** Register a listener for `event`. Returns `this` for chaining. */
  on<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this {
    this.#entriesFor(event).push({ listener, once: false, removed: false });
    return this;
  }

  /**
   * Register a listener that fires at most once and is automatically removed
   * before it is invoked. It can still be cancelled with {@link off} before
   * it ever fires.
   */
  once<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this {
    this.#entriesFor(event).push({ listener, once: true, removed: false });
    return this;
  }

  /** Remove a previously registered listener. No-op if it isn't registered. */
  off<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this {
    const entries = this.#listeners.get(event);
    if (entries) removeEntry(entries, listener);
    return this;
  }

  /**
   * Register a wildcard listener invoked for every emitted event with the
   * event name as the first argument, followed by the event's arguments.
   * Named listeners always run before wildcard listeners.
   */
  onAny(listener: (event: keyof Events, ...args: unknown[]) => void): this {
    this.#anyListeners.push({ listener, once: false, removed: false });
    return this;
  }

  /** Remove a previously registered wildcard listener. */
  offAny(listener: (event: keyof Events, ...args: unknown[]) => void): this {
    removeEntry(this.#anyListeners, listener);
    return this;
  }

  /**
   * Emit `event` with `args`. Listeners registered at the time of the call run
   * in registration order; removing any listener during the emit (including
   * the currently running one) never prevents the remaining listeners from
   * running. Returns `true` if any listener (named or wildcard) was called.
   */
  emit<K extends keyof Events>(event: K, ...args: Events[K]): boolean {
    let delivered = false;

    const entries = this.#listeners.get(event);
    if (entries && entries.length > 0) {
      delivered = true;
      invoke(entries.slice(), args);
    }

    if (this.#anyListeners.length > 0) {
      delivered = true;
      invoke(this.#anyListeners.slice(), [event, ...args]);
    }

    return delivered;
  }

  #entriesFor(event: keyof Events): Entry[] {
    let entries = this.#listeners.get(event);
    if (!entries) {
      entries = [];
      this.#listeners.set(event, entries);
    }
    return entries;
  }
}

/** Run a snapshot of entries; skips entries removed after the snapshot was taken. */
function invoke(snapshot: Entry[], args: unknown[]): void {
  for (const entry of snapshot) {
    if (entry.removed) continue;
    // Detach `once` handlers before invoking so re-entrant emits don't
    // deliver the event to them twice.
    if (entry.once) entry.removed = true;
    entry.listener(...args);
  }
}

/** Mark matching entries removed and drop them from the live list. */
function removeEntry(entries: Entry[], listener: ListenerFn): void {
  for (let i = 0; i < entries.length; i++) {
    if (entries[i]!.listener === listener) {
      entries[i]!.removed = true;
      entries.splice(i, 1);
      i--;
    }
  }
}
