import { Emitter } from './emitter.js';

interface Events {
  foo: [text: string, count: number];
  bar: [flag: boolean];
}

const emitter = new Emitter<Events>();

// Correct usage compiles cleanly.
emitter.emit('foo', 'hello', 42);
emitter.emit('bar', true);
