  expect(count).toEqual(expect.any(Number));
});

describe('type-level negative cases (verified by tsc --noEmit)', () => {
  it('rejects emitting with wrong argument types', () => {
    // @ts-expect-error second argument must be number, not string
    emitter.emit('foo', 'hello', 'not-a-number');

    // @ts-expect-error boolean is not assignable to the foo tuple
    emitter.emit('foo', true);

    // @ts-expect-error missing required argument
    emitter.emit('foo', 'hello');

    // @ts-expect-error too many arguments
    emitter.emit('bar', true, 'extra');

    // @ts-expect-error unknown event name
    emitter.emit('nope', 1);
  });

  it('rejects listeners with incompatible signatures', () => {
    // @ts-expect-error listener parameter must be string, got number
    emitter.on('foo', (text: number) => {});

    // @ts-expect-error wrong arity: foo has two args
    emitter.on('foo', (text: string, count: number, extra: boolean) => {});

    // @ts-expect-error unknown event name on registration
    emitter.on('nope', () => {});
  });

  it('rejects once/off/onAny misuse', () => {
    // @ts-expect-error once with wrong arg type
    emitter.once('bar', (flag: string) => {});

    // @ts-expect-error off for an unknown event
    emitter.off('nope', () => {});

    // @ts-expect-error wildcard listener's first param is not an event name
    emitter.onAny((event: string) => {});
  });

  it('exposes precise listener types', async () => {
    const { expectTypeOf } = await import('expect-type');

    // A correctly-typed listener assigns fine.
    const ok = (text: string, count: number): void => {};
    expectTypeOf(ok).toExtend<(text: string, count: number) => void>();

    // Emit returns whether anyone listened.
    expectTypeOf(emitter.emit('bar', false)).toEqualTypeOf<boolean>();

    // on/once/off return the emitter for chaining.
    expectTypeOf(emitter.on('bar', (f) => undefined)).toEqualTypeOf<Emitter<Events>>();
  });
